13	func TestRetryTransport_RetriesOnRetryableStatus(t *testing.T) {
14		t.Parallel()
15	
16		var calls int
17		next := roundTripperFunc(func(req *http.Request) (*http.Response, error) {
18			calls++
19			status := 502
20			if calls == 2 {
21				status = 200
22			}
23			return &http.Response{
24				StatusCode: status,
25				Header:     make(http.Header),
26				Body:       io.NopCloser(strings.NewReader("")),
27				Request:    req,
28			}, nil
29		})
30	
31		var sleeps []time.Duration
32		sleep := func(_ context.Context, d time.Duration) error {
33			sleeps = append(sleeps, d)
34			return nil
35		}
36	
37		policy := DefaultRetryPolicy()
38		policy.BaseDelay = 1 * time.Millisecond
39		policy.MaxDelay = 1 * time.Millisecond
40		policy.Jitter = func(d time.Duration) time.Duration { return d }
41	
42		rt := newRetryTransport(next, policy, retryTransportOptions{
43			sleep: sleep,
44			now:   func() time.Time { return time.Unix(0, 0).UTC() },
45		})
46	
47		req, _ := http.NewRequestWithContext(context.Background(), http.MethodGet, "https://example.test", nil)
48		resp, err := rt.RoundTrip(req)
49		if err != nil {
50			t.Fatalf("unexpected error: %v", err)
51		}
